// The World operator's part: the verification machine pool (kind fake: it records what it is asked and runs no
// process) and the already-built task-agent image registered in the deployment's project, as the Runhuman operator does.
import assert from 'node:assert/strict';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
const door = (path, body) => fetch(`${process.env.E2B_TWIN_URL}/_twin/${path}`, { method: 'POST', headers: { 'content-type': 'application/json', 'x-api-key': process.env.E2B_API_KEY }, body: JSON.stringify(body) });
const pool = await door('machine-pool', { kind: 'fake' });
assert.equal(pool.status, 201, await pool.clone().text());
const template = await door('templates', { alias: 'runhuman-task-agent', image: 'runhuman/task-agent:local', command: ['sleep', 'infinity'], cpuCount: 2, memoryMB: 2048, diskSizeMB: 10240 });
assert.equal(template.status, 201, await template.clone().text());
console.log(JSON.stringify({ pool: 'fake', template: (await template.json()).templateID }));

