// RH2's Task machine (bots/runhuman-model/machine.ts at 34fdc937): E2B's REST API with fetch and x-api-key for the
// sandbox's life, and the sandbox's envd process door (Connect over HTTP) to start the Task agent host.
import assert from 'node:assert/strict';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
const API = 'https://api.e2b.app';
const env = { E2B_API_KEY: process.env.E2B_API_KEY, TASK_MACHINE_TEMPLATE: process.env.TASK_MACHINE_TEMPLATE || 'runhuman-task-agent' };
const MACHINE_LIFETIME_S = 60 * 60;
async function stopTaskMachine(sandboxId) {
  const response = await fetch(`${API}/sandboxes/${encodeURIComponent(sandboxId)}`, { headers: { 'x-api-key': env.E2B_API_KEY }, method: 'DELETE' });
  if (!response.ok && response.status !== 404) throw new Error(`the Task's machine did not stop: ${response.status}`);
  return response.status;
}
async function startTaskMachine(envVars) {
  const created = await fetch(`${API}/sandboxes`, { body: JSON.stringify({ envVars, templateID: env.TASK_MACHINE_TEMPLATE, timeout: MACHINE_LIFETIME_S }), headers: { 'content-type': 'application/json', 'x-api-key': env.E2B_API_KEY }, method: 'POST' });
  if (!created.ok) throw new Error(`the Task's machine did not start: ${created.status} ${(await created.text()).slice(0, 200)}`);
  const { sandboxID, domain } = await created.json();
  const message = new TextEncoder().encode(JSON.stringify({ process: { args: ['-l', '-c', 'cd /app && curl -fsSL "$RH2_BASE_URL/v1/companion/host.mjs" -o host.mjs && curl -fsSL "$RH2_BASE_URL/v1/companion/room-tools.mjs" -o room-tools.mjs && nohup node host.mjs > /tmp/host.log 2>&1 &'], cmd: '/bin/bash', envs: {} } }));
  const envelope = new Uint8Array(5 + message.byteLength);
  new DataView(envelope.buffer).setUint32(1, message.byteLength);
  envelope.set(message, 5);
  const started = await fetch(`https://49983-${sandboxID}.${domain ?? 'e2b.app'}/process.Process/Start`, { body: envelope, headers: { 'connect-protocol-version': '1', 'content-type': 'application/connect+json', 'e2b-sandbox-id': sandboxID, 'e2b-sandbox-port': '49983' }, method: 'POST', signal: AbortSignal.timeout(30_000) });
  let events = '';
  const reader = started.body?.getReader();
  const decoder = new TextDecoder();
  try {
    while (reader && !/"start":\{"pid":\d+/.test(events)) {
      const { done, value } = await reader.read();
      if (done) break;
      events += decoder.decode(value, { stream: true });
    }
  } catch { /* a stream cut short is judged by what it said */ }
  await reader?.cancel().catch(() => undefined);
  if (!started.ok || !/"start":\{"pid":\d+/.test(events)) {
    await stopTaskMachine(sandboxID);
    throw new Error(`the Task's AI did not start in its machine: ${started.status} ${events.slice(0, 200)}`);
  }
  return { sandboxID, domain, pid: Number(/"start":\{"pid":(\d+)/.exec(events)[1]) };
}
const machine = await startTaskMachine({ RH2_BASE_URL: 'https://pilot.runhuman.com', TASK_ID: 'task_1' });
assert.ok(machine.sandboxID);
assert.ok(machine.pid > 0);
const running = await (await fetch(`${API}/v2/sandboxes`, { headers: { 'x-api-key': env.E2B_API_KEY } })).json();
assert.deepEqual(running.map((s) => s.sandboxID), [machine.sandboxID]);
assert.equal(await stopTaskMachine(machine.sandboxID), 204);
assert.equal(await stopTaskMachine(machine.sandboxID), 404);
console.log(JSON.stringify({ started: machine.sandboxID, domain: machine.domain, pid: machine.pid, ended: true }));

