// The operator's audit the next morning: no Task machine left running, the task-agent template ready.
import assert from 'node:assert/strict';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
const headers = { 'x-api-key': process.env.E2B_API_KEY };
const sandboxes = await (await fetch('https://api.e2b.app/v2/sandboxes', { headers })).json();
assert.deepEqual(sandboxes, []);
const templates = await (await fetch('https://api.e2b.app/v2/templates', { headers })).json();
const agent = templates.find((t) => t.aliases?.includes('runhuman-task-agent') || t.alias === 'runhuman-task-agent');
assert.ok(agent, JSON.stringify(templates).slice(0, 300));
assert.equal(agent.buildStatus, 'ready');
console.log(JSON.stringify({ retained: true, sandboxes: sandboxes.length, template: agent.templateID, buildStatus: agent.buildStatus }));
